// Bollard UI — link-text-check · MIT licence · https://bollard-ui.vercel.app/components/link-text-check

export interface LinkItem {
  /** The link's accessible name: its text, aria-label or image alt. */
  text: string
  href: string
  /** Sentence text before the link, used to suggest a rewrite. */
  before?: string
  /** Sentence text after the link. */
  after?: string
  /** Markdown offsets of the whole link, and of the sentence it sits in. */
  start?: number
  end?: number
  sentenceStart?: number
  sentenceEnd?: number
  /** Reference-style link label (`[text][ref]`); rewrites keep the reference. */
  ref?: string
  /** A linked image (`[![alt](img)](url)`): the alt text is the link text, so it is fixed in the image, not rewritten. */
  image?: boolean
  element?: HTMLElement
}

export type LinkIssue = "empty" | "generic" | "url" | "same-text"

export interface LinkCheck {
  issue?: LinkIssue
  /** Better link text, when one can be worked out. */
  suggestion?: string
  /** Markdown edit that applies the suggestion (rewrites the sentence around "click here"). */
  edit?: { from: number; to: number; insert: string }
  /** Where the other links with this text go (same-text). */
  others?: string[]
}

/** Link text that means nothing out of context (WCAG F84). Lowercase, without punctuation. */
export const GENERIC_LINK_TEXT = [
  "click here", "click", "here", "tap here", "this", "this link", "link", "read more", "learn more", "more",
  "more info", "more information", "details", "see more", "find out more", "continue", "continue reading",
  "go", "download", "info", "website", "this page", "page", "here's how",
]

const LINK = new RegExp(
  [
    String.raw`\[!\[(?<alt>[^\]\n]*)\]\([^)\n]*\)\]\(\s*<?(?<imageHref>[^)\s>]*)>?(?:\s+"[^"]*")?\s*\)`,
    String.raw`(?<bang>!?)\[(?<text>[^\]\n]*)\]\(\s*<?(?<href>[^)\s>]*)>?(?:\s+"[^"]*")?\s*\)`,
    String.raw`(?<refBang>!?)\[(?<refText>[^\]\n]+)\]\[(?<ref>[^\]\n]*)\]`,
    String.raw`<(?<angle>https?:\/\/[^>\s]+)>`,
    String.raw`(?<bare>https?:\/\/[^\s<>()[\]]*[^\s<>()[\].,;:!?'"])`,
  ].join("|"),
  "g",
)
const DEFINITION = /^ {0,3}\[([^\]\n]+)\]:[ \t]*<?([^\s>]+)>?.*$/gm
const blank = (text: string) => text.replace(/[^\n]/g, " ")
/** Blanks code (fenced blocks and inline spans) and link definitions, keeping offsets, so nothing inside them reads as a link. */
const maskCode = (markdown: string) =>
  markdown
    .replace(/^ {0,3}(`{3,}|~{3,})[^\n]*\n[\s\S]*?(?:^ {0,3}\1[^\n]*$|(?![\s\S]))/gm, blank)
    .replace(/(`+)(?!`)[\s\S]*?(?<!`)\1(?!`)/g, blank)
    .replace(DEFINITION, blank)
/** The Markdown for a link with new text, in the same style it was written; null when it can't be rewritten in place. */
const markup = (link: LinkItem, text: string) => (link.image ? null : link.ref !== undefined ? `[${text}][${link.ref}]` : `[${text}](${link.href})`)
const normal = (text: string) => text.toLowerCase().replace(/[\s\u00a0]+/g, " ").replace(/^[^\p{L}\p{N}]+|[^\p{L}\p{N}]+$/gu, "")
const capital = (text: string) => text.charAt(0).toUpperCase() + text.slice(1)

/** Strips tracking parameters, a trailing slash and host case so the same page compares equal. */
export function normalizeHref(href: string) {
  try {
    const url = new URL(href, "https://relative.invalid")
    ;[...url.searchParams.keys()].filter((k) => /^(utm_|fbclid|gclid)/.test(k)).forEach((k) => url.searchParams.delete(k))
    const host = url.host === "relative.invalid" ? "" : url.host.replace(/^www\./, "")
    return `${host}${url.pathname.replace(/\/$/, "")}${url.search}${url.hash}` || "/"
  } catch {
    return href
  }
}

/** Is this link text just a URL (beyond a short bare domain like devtushar.tech)? */
export function isUrlText(text: string, href = "") {
  const t = text.trim()
  if (!/^(https?:\/\/|www\.)\S+$/i.test(t) && normalizeHref(t) !== normalizeHref(href)) return false
  const bare = t.replace(/^https?:\/\//i, "").replace(/^www\./i, "").replace(/\/$/, "")
  return bare.includes("/") || bare.includes("?") || bare.length > 24
}

/** Readable words from a URL: /reports/annual-report-2026.pdf → "Annual report 2026 (PDF)". */
export function describeHref(href: string) {
  const contact = href.match(/^(?:mailto|tel):([^?]+)/i)?.[1]
  if (contact) return decodeURIComponent(contact)
  try {
    const url = new URL(href, "https://relative.invalid")
    const host = url.host === "relative.invalid" ? "" : url.host.replace(/^www\./, "")
    const segment = decodeURIComponent(url.pathname.split("/").filter(Boolean).pop() ?? "")
    const ext = segment.match(/\.(pdf|docx?|xlsx?|csv|zip)$/i)?.[1]
    const words = segment
      .replace(/\.[a-z0-9]+$/i, "")
      .split(/[-_+]+/)
      .filter((w) => !(w.length >= 6 && /\d/.test(w) && /[a-z]/i.test(w)) && !/^[0-9a-f]{8,}$/i.test(w))
      .join(" ")
      .trim()
    // One-letter or numeric slugs ("/b", "/2041") say nothing; the site's name is better, or nothing at all.
    if (words.replace(/\s/g, "").length < 3 || /^\d+$/.test(words)) return host
    return `${capital(words)}${ext ? ` (${ext.toUpperCase()})` : ""}`
  } catch {
    return ""
  }
}

/** Finds Markdown links ([text](url), <url> and bare URLs, which GFM turns into links) with their sentence around them. */
export function linksFromMarkdown(markdown: string): LinkItem[] {
  const out: LinkItem[] = []
  const definitions = new Map([...markdown.matchAll(DEFINITION)].map((d) => [d[1].trim().toLowerCase(), d[2]]))
  for (const m of maskCode(markdown).matchAll(LINK)) {
    const g = m.groups ?? {}
    if (g.bang || g.refBang) continue
    const ref = g.refText === undefined ? undefined : g.ref
    const refHref = ref === undefined ? undefined : definitions.get((ref || g.refText).trim().toLowerCase())
    if (ref !== undefined && refHref === undefined) continue
    const start = m.index
    const end = start + m[0].length
    const sentenceStart = Math.max(0, ...[". ", "! ", "? ", "\n"].map((s) => {
      const at = markdown.lastIndexOf(s, start - 1)
      return at < 0 ? 0 : at + s.length
    }))
    const stop = markdown.slice(end).search(/[.!?](\s|$)|\n/)
    const sentenceEnd = stop < 0 ? markdown.length : end + stop
    const text = g.alt ?? g.text ?? g.refText ?? g.angle ?? g.bare
    const href = g.imageHref ?? g.href ?? refHref ?? g.angle ?? g.bare
    out.push({ text, href, start, end, sentenceStart, sentenceEnd, before: markdown.slice(sentenceStart, start), after: markdown.slice(end, sentenceEnd), ref, image: g.alt !== undefined || undefined })
  }
  return out
}

const hidden = (el: Element) =>
  !!el.closest("[hidden],[aria-hidden=true]") || (el instanceof HTMLElement && !!el.checkVisibility && !el.checkVisibility({ visibilityProperty: true }))

/** Text a screen reader reads for an element's content: skips hidden parts, uses image alt and SVG titles. */
function contentName(node: Node): string {
  if (node.nodeType === Node.TEXT_NODE) return node.textContent ?? ""
  if (!(node instanceof Element) || node.matches("[hidden],[aria-hidden=true]") || (node instanceof HTMLElement && node.checkVisibility && !node.checkVisibility())) return ""
  const label = node.getAttribute("aria-label")
  if (label && node !== node.closest("a")) return ` ${label} `
  if (node instanceof HTMLImageElement) return ` ${node.alt} `
  if (node.localName === "svg") return ` ${node.querySelector("title")?.textContent ?? ""} `
  const inline = node instanceof HTMLElement && /^(inline|contents)/.test(getComputedStyle(node).display)
  const inner = [...node.childNodes].map(contentName).join("")
  return inline ? inner : ` ${inner} `
}

/** The link's accessible name, close to what browsers compute: aria-labelledby, aria-label, content, then title. */
export function accessibleLinkName(a: HTMLElement) {
  const ids = a.getAttribute("aria-labelledby")?.split(/\s+/).filter(Boolean) ?? []
  const labelled = ids.map((id) => a.ownerDocument.getElementById(id)?.textContent ?? "").join(" ")
  const name = labelled.trim() || a.getAttribute("aria-label")?.trim() || contentName(a).trim() || a.getAttribute("title") || ""
  return name.replace(/\s+/g, " ").trim()
}

/** Reads the links inside an element as a screen reader names them, skipping hidden ones and this checker itself. */
export function linksFromElement(root: HTMLElement): LinkItem[] {
  return [...root.querySelectorAll<HTMLAnchorElement>("a[href]")]
    .filter((a) => !hidden(a) && !a.closest("[data-slot=link-text-check]"))
    .map((a) => {
      const text = accessibleLinkName(a)
      const block = a.closest("p,li,td,dd,blockquote") ?? a.parentElement
      const full = block?.textContent ?? ""
      const at = full.indexOf(a.textContent ?? "")
      const before = at < 0 ? "" : full.slice(0, at).split(/[.!?]\s/).pop()
      const after = at < 0 ? "" : full.slice(at + (a.textContent ?? "").length).split(/[.!?](\s|$)/)[0]
      return { text, href: a.getAttribute("href") ?? "", before, after, element: a }
    })
}

/** Lifts the words that explain a vague link into the link: "To download the report, [click here](…)" → "[Download the report](…)". */
function rewrite(link: LinkItem): Pick<LinkCheck, "suggestion" | "edit"> {
  const lead = link.before?.match(/^\s*(?:to|if you(?:'d| would)? (?:like|want) to|you can|please|for)\s+(?:the\s+)?(.+?)[\s,:;–-]*(?:please\s*)?$/i)
  const tail = link.after?.match(/^\s*to\s+(.+?)\s*$/i)
  const words = lead?.[1] ?? tail?.[1]
  if (!words || words.split(" ").length > 12) {
    const fromUrl = describeHref(link.href)
    const insert = fromUrl ? markup(link, fromUrl) : null
    return fromUrl ? { suggestion: fromUrl, edit: link.start === undefined || !insert ? undefined : { from: link.start, to: link.end!, insert } } : {}
  }
  const suggestion = capital(words)
  const insert = markup(link, suggestion)
  if (link.start === undefined || !insert) return { suggestion }
  const before = link.before!
  const indent = before.length - before.trimStart().length
  const fromSentence = !!lead || /^\s*(please\s*)?$/i.test(before)
  const from = fromSentence ? link.sentenceStart! + indent : link.start
  return { suggestion, edit: { from, to: lead ? link.end! : link.sentenceEnd!, insert } }
}

/** Checks each link's text against WCAG 2.4.4: vague text, URLs as text, empty links, and one text for two destinations. */
export function checkLinks(links: LinkItem[], genericText: string[] = GENERIC_LINK_TEXT): LinkCheck[] {
  const generic = new Set(genericText.map(normal))
  const targets = new Map<string, Set<string>>()
  links.forEach((l) => targets.set(normal(l.text), (targets.get(normal(l.text)) ?? new Set()).add(normalizeHref(l.href))))
  return links.map((link): LinkCheck => {
    const text = normal(link.text)
    const edit = (suggestion: string) => {
      const insert = suggestion && link.start !== undefined ? markup(link, suggestion) : null
      return insert ? { from: link.start!, to: link.end!, insert } : undefined
    }
    if (!text) {
      const suggestion = describeHref(link.href) || undefined
      return { issue: "empty", suggestion, edit: suggestion ? edit(suggestion) : undefined }
    }
    if (generic.has(text)) return { issue: "generic", ...rewrite(link) }
    if (isUrlText(link.text, link.href)) {
      const suggestion = describeHref(link.href)
      return { issue: "url", suggestion: suggestion || undefined, edit: edit(suggestion) }
    }
    const places = targets.get(text)!
    if (places.size > 1) return { issue: "same-text", others: [...places].filter((p) => p !== normalizeHref(link.href)) }
    return {}
  })
}

"use client"

// Bollard UI — link-text-check · MIT licence · https://bollard-ui.vercel.app/components/link-text-check

import * as React from "react"
import { CircleCheck, Link2, TriangleAlert } from "lucide-react"

import { cn } from "@/lib/utils"
import { checkLinks, GENERIC_LINK_TEXT, linksFromElement, linksFromMarkdown, normalizeHref, type LinkItem } from "./link-rules"

export { accessibleLinkName, checkLinks, describeHref, GENERIC_LINK_TEXT, isUrlText, linksFromElement, linksFromMarkdown, normalizeHref } from "./link-rules"
export type { LinkCheck, LinkIssue, LinkItem } from "./link-rules"

export const LINK_TEXT_MESSAGES = {
  generic: (text: string) => `“${text}” doesn't say where it goes, and screen reader users often browse links out of context.`,
  url: "A full URL is read out character by character.",
  empty: "No text, so it's announced as just “link”.",
  sameText: (count: number) => `Same text as ${count === 1 ? "a link" : `${count} links`} going somewhere else:`,
}

const fixClass =
  "inline-flex min-h-6 max-w-full items-center rounded-md py-0.5 text-left border border-amber-500/40 px-2 text-xs font-medium text-amber-900 transition-colors hover:bg-amber-500/10 dark:text-amber-200 outline-none focus-visible:ring-[3px] focus-visible:ring-ring/50"
const tabClass =
  "h-7 rounded px-2.5 text-xs font-medium outline-none transition-colors focus-visible:ring-[3px] focus-visible:ring-ring/50 aria-pressed:bg-background aria-pressed:shadow-xs aria-[pressed=false]:text-muted-foreground dark:aria-pressed:bg-input/50"

export interface LinkTextCheckProps extends Omit<React.ComponentProps<"section">, "children"> {
  /** Markdown to check. With `onMarkdownChange`, problems get one-tap rewrites. */
  markdown?: string
  /** Called with the rewritten Markdown when a fix is tapped. */
  onMarkdownChange?: (markdown: string) => void
  /** Live mode: check the links inside this element as it changes. Rows focus the link. */
  target?: React.RefObject<HTMLElement | null>
  /** Called when a link is chosen (markdown mode), e.g. to select it in the editor. */
  onJump?: (link: LinkItem) => void
  /** Text treated as meaningless out of context. Replace it to translate. */
  genericText?: string[]
  /** Heading shown above the check. */
  title?: string
  /** `{count}` is filled in. */
  summaryText?: string
  /** Shown when no problems are found. */
  allGoodText?: string
  /** Shown when there are no links. */
  emptyText?: string
  /** Accessible label for the issues list. */
  issuesLabel?: string
  /** Heading for the links-list preview. */
  listLabel?: string
  /** Explains the links-list preview. */
  listHint?: string
  /** Shown in place of the text of an empty link. */
  emptyLinkText?: string
  /** Prefix a screen reader says before each link. */
  linkRoleText?: string
  /** `{text}` is filled in. */
  fixLabel?: string
  /** Shown instead of a fix in live mode. `{text}` is filled in. */
  tryText?: string
  /** Override any issue message. */
  messages?: Partial<typeof LINK_TEXT_MESSAGES>
}

/**
 * Catches link text that fails people browsing a screen reader's links list: "click here" and "read more",
 * URLs as text, empty links, and one text pointing to two different places. Vague links get a rewrite that lifts
 * the words around them into the link ("To download the report, click here" → "Download the report"), and a
 * second view shows the links list exactly as it will be read out.
 */
export function LinkTextCheck({
  markdown,
  onMarkdownChange,
  target,
  onJump,
  genericText = GENERIC_LINK_TEXT,
  title = "Links",
  summaryText = "{count} to fix",
  allGoodText = "Every link says where it goes",
  emptyText = "No links yet.",
  issuesLabel = "Issues",
  listLabel = "Links list",
  listHint = "How a screen reader's links list reads them, out of context:",
  emptyLinkText = "No text",
  linkRoleText = "link",
  fixLabel = "Use “{text}”",
  tryText = "Try “{text}”",
  messages,
  className,
  ...props
}: LinkTextCheckProps) {
  const [live, setLive] = React.useState<LinkItem[]>([])
  const [view, setView] = React.useState<"issues" | "list">("issues")
  React.useEffect(() => {
    const root = target?.current
    if (!root) return
    // Only re-render when the links really changed, so checking a region that contains this checker can't loop.
    const read = () => {
      const next = linksFromElement(root)
      setLive((current) =>
        current.length === next.length && current.every((l, i) => l.element === next[i].element && l.text === next[i].text && l.href === next[i].href) ? current : next,
      )
    }
    read()
    const observer = new MutationObserver(read)
    observer.observe(root, { subtree: true, childList: true, characterData: true, attributes: true, attributeFilter: ["href", "aria-label", "aria-labelledby", "aria-hidden", "title", "alt", "hidden", "class", "style"] })
    return () => observer.disconnect()
  }, [target])

  const links = React.useMemo(() => (target ? live : linksFromMarkdown(markdown ?? "")), [target, live, markdown])
  const checks = React.useMemo(() => checkLinks(links, genericText), [links, genericText])
  const t = { ...LINK_TEXT_MESSAGES, ...messages }
  const flagged = links.map((link, i) => ({ link, check: checks[i] })).filter((row) => row.check.issue)
  const canFix = !target && !!onMarkdownChange && markdown !== undefined
  const issuesList = React.useRef<HTMLUListElement>(null)
  // A tapped fix removes its card, so focus moves to the next fix (or the first card) instead of the page.
  const refocus = React.useRef<number | null>(null)
  React.useEffect(() => {
    if (refocus.current === null) return
    const fixes = issuesList.current?.querySelectorAll<HTMLButtonElement>("button[data-fix]") ?? []
    ;(fixes[Math.min(refocus.current, fixes.length - 1)] ?? issuesList.current?.querySelector<HTMLButtonElement>("button:not(:disabled)"))?.focus()
    refocus.current = null
  }, [markdown])

  const jump = (link: LinkItem) => {
    if (!link.element) return onJump?.(link)
    link.element.scrollIntoView({ block: "center", behavior: matchMedia("(prefers-reduced-motion: reduce)").matches ? "auto" : "smooth" })
    link.element.focus({ preventScroll: true })
  }
  const message = (link: LinkItem, check: (typeof checks)[number]) =>
    check.issue === "generic" ? t.generic(link.text.trim()) : check.issue === "url" ? t.url : check.issue === "empty" ? t.empty : t.sameText(check.others?.length ?? 1)

  return (
    <section data-slot="link-text-check" data-state={flagged.length ? "issues" : "ok"} aria-label={title} className={cn("w-full max-w-md rounded-lg border p-3 text-sm", className)} {...props}>
      <div className="mb-2 flex flex-wrap items-center justify-between gap-2">
        <p className="flex items-center gap-1.5 font-medium">
          <Link2 aria-hidden className="size-4 text-muted-foreground" />
          {title}
          {links.length > 0 && (
            <span aria-live="polite" className={cn("ms-1 flex items-center gap-1 text-xs font-normal", flagged.length ? "text-amber-700 dark:text-amber-400" : "text-emerald-700 dark:text-emerald-400")}>
              {flagged.length ? <TriangleAlert aria-hidden className="size-3.5" /> : <CircleCheck aria-hidden className="size-3.5" />}
              {flagged.length ? summaryText.replace("{count}", String(flagged.length)) : allGoodText}
            </span>
          )}
        </p>
        {links.length > 0 && (
          <div className="flex rounded-md bg-muted p-0.5">
            <button type="button" aria-pressed={view === "issues"} onClick={() => setView("issues")} className={tabClass}>{issuesLabel}</button>
            <button type="button" aria-pressed={view === "list"} onClick={() => setView("list")} className={tabClass}>{listLabel}</button>
          </div>
        )}
      </div>
      {links.length === 0 && <p className="text-muted-foreground">{emptyText}</p>}
      {view === "list" && links.length > 0 && (
        <div className="grid gap-1.5">
          <p className="text-xs text-muted-foreground">{listHint}</p>
          <ol className="grid list-decimal gap-1 ps-6 text-sm marker:text-xs marker:text-muted-foreground">
            {links.map((link, i) => (
              <li key={i} data-issue={checks[i].issue} className={cn("break-words", checks[i].issue && "text-amber-700 dark:text-amber-400")}>
                <span className="text-muted-foreground">{linkRoleText}, </span>
                {link.text.trim() || "…"}
              </li>
            ))}
          </ol>
        </div>
      )}
      {view === "issues" && (
        <ul ref={issuesList} className="grid gap-2">
          {flagged.map(({ link, check }) => {
            const index = links.indexOf(link)
            const label = link.text.trim()
            return (
              <li key={index} data-issue={check.issue} className="grid min-w-0 gap-1 rounded-md border p-2.5">
                <button type="button" onClick={() => jump(link)} disabled={!link.element && !onJump} className="flex min-w-0 items-baseline gap-2 rounded text-left outline-none enabled:hover:bg-accent focus-visible:ring-[3px] focus-visible:ring-ring/50">
                  <span className={cn("min-w-0 shrink truncate font-medium", !label && "italic text-muted-foreground")}>{label ? `“${label}”` : emptyLinkText}</span>
                  <span className="min-w-0 flex-1 truncate font-mono text-xs text-muted-foreground">→ {normalizeHref(link.href)}</span>
                </button>
                <p className={cn("text-xs", check.issue === "empty" ? "text-red-700 dark:text-red-400" : "text-amber-700 dark:text-amber-400")}>{message(link, check)}</p>
                {check.others && (
                  <ul className="grid gap-0.5 ps-3 font-mono text-xs text-muted-foreground">
                    {check.others.map((other) => <li key={other} className="truncate">→ {other}</li>)}
                  </ul>
                )}
                {check.suggestion && (canFix && check.edit ? (
                  <button
                    type="button"
                    data-fix=""
                    className={cn(fixClass, "mt-0.5 min-w-0 justify-self-start")}
                    onClick={(event) => {
                      refocus.current = [...(issuesList.current?.querySelectorAll("button[data-fix]") ?? [])].indexOf(event.currentTarget)
                      onMarkdownChange!(markdown!.slice(0, check.edit!.from) + check.edit!.insert + markdown!.slice(check.edit!.to))
                    }}
                  >
                    <span className="break-words">{fixLabel.replace("{text}", check.suggestion)}</span>
                  </button>
                ) : (
                  <p className="text-xs text-muted-foreground">{tryText.replace("{text}", check.suggestion)}</p>
                ))}
              </li>
            )
          })}
        </ul>
      )}
    </section>
  )
}
